LibEmote=LibEmote or{}LibEmote.Emote=LibEmote.Emote or{}function LibEmote.Emote:new(a)local b=a or{}setmetatable(b,self)self.__index=self;b.textures=b.textures or{LibEmote.GetMissing()}b.scale=b.scale or 1;b.name=b.name or""b.searchName=b.name:lower()b.emoteIndex=b.emoteIndex or"0"b.isReference=b.isReference or false;b.reference=b.reference or""return b end;function LibEmote.Emote:getTexture(c)return self.textures[c or 1]or LibEmote.GetMissing()end;function LibEmote.Emote:toggleFavorite()if self:getFavorite()==1 then self:setFavorite(0)else self:setFavorite(1)end end;function LibEmote.Emote:setFavorite(e)LibEmote.savedVars.favorites[self.name]=e end;function LibEmote.Emote:getFavorite()return LibEmote.savedVars.favorites[self.name]or 0 end